// --- budgets (compat/ `budgets`, gate-2.0.0 rows) ---------------------------

/// The heartbeat answer is read into this; the server sends at most 6144.
constexpr size_t kGateHeartbeatResponseCap = 8192U;
/// The `/gate` scan decision (FC-6: 1.x read it into 128 and an over-cap body
/// became status 0, which taught the breaker the server was down).
constexpr size_t kGateScanResponseCap = 256U;
/// The `/events` reply, frozen at two keys and at most 96 bytes (FC-5).
constexpr size_t kGateEventsResponseCap = 192U;
/// The heartbeat request, rendered with telemetry.
constexpr size_t kGateHeartbeatRequestCap = 1536U;

// --- drift -----------------------------------------------------------------

constexpr uint8_t kMaxDrift = 8U;
constexpr size_t kDriftNameCap = 40U;

/// Up to eight names of keys the board could not read in one answer, reported
/// in the NEXT request (device-api.md §2).
struct Drift {
  char names[kMaxDrift][kDriftNameCap] = {};
  uint8_t count = 0U;

  void clear() { count = 0U; }
  void add(const char* name);
  bool contains(const char* name) const;
};

// --- the gate object --------------------------------------------------------

/// What `gate` carries. Defaults are the build flags until a heartbeat says
/// otherwise; bounds are the compat reference's clamps.
struct GateSettings {
  uint32_t unlockSeconds = 15U;
  uint32_t powerRestoreTrustMinutes = 20U;
  uint32_t netFallbackMinutes = 10U;
  uint32_t otaProbationMinutes = 10U;
  bool faultReporting = true;
  uint32_t faultMaxPerHour = 60U;
};

/// The board's settings before any heartbeat: the build flags.
GateSettings compiledGateSettings();

/// Reads `gate` (the member's value, any kind) into `settings`. A non-object is
/// drift "gate"; each setting present with the wrong kind is drift
/// "gate.<key>" and keeps its previous value; an integer out of range clamps.
/// Returns whether `unlock_seconds` was present but outside [1, 30].
bool readGateSettings(const jv::Value& gate, GateSettings& settings, Drift& drift);

// --- element grammars -------------------------------------------------------

/// One roster element by its first four fields, relay 0 only (a door is not on
/// a court). False for anything unreadable.
bool readRosterElement(const jv::Value& element, roster::Entry& out);

/// One `code_days` element by its first two fields.
bool readDayElement(const jv::Value& element, memcode::DaySlot& out);

/// One `code_keys` element: its first 21 characters, followed by nothing or `|`.
bool readKeyElement(const jv::Value& element, memcode::DayKey& out);

// --- images ----------------------------------------------------------------

/// The roster as adopted: elements in server order, anchored at the millis
/// instant they were read (their seconds are relative to that instant).
struct RosterImage {
  roster::Entry entries[kGateRosterEntries];
  uint8_t count = 0U;
  uint32_t anchorMs = 0U;
  bool loaded = false;
};

/// The member-code day slots and keys as adopted.
struct CodeImage {
  memcode::DaySlot days[memcode::kMaxDaySlots];
  memcode::DayKey keys[kGateKeyRingSlots];
  uint8_t count = 0U;
};

/// The member-code step clock's last sync, as adopted.
struct StepImage {
  uint32_t step = 0U;
  uint32_t stepMs = 0U;
  uint32_t anchorMs = 0U;
  bool synced = false;
};

/// What one array did to its image.
enum class ArrayRead : uint8_t {
  Absent = 0U,   ///< no key: no opinion
  Adopted = 1U,  ///< committed (possibly empty)
  Kept = 2U,     ///< present but nothing readable: the previous value stands, drift
};

ArrayRead readRoster(const jv::Value& body, RosterImage& image, uint32_t nowMs, Drift& drift);

/// `code_days` and `code_keys`, each independently. A key whose day slot is not
/// one this answer (or the kept image) defines is still kept: the slot index is
/// the server's, and days and keys are sent together.
void readCodes(const jv::Value& body, CodeImage& image, Drift& drift, ArrayRead& days, ArrayRead& keys);

/// `code_step` and `code_step_ms`, both or neither, exact kinds.
bool readStepClock(const jv::Value& body, StepImage& image, uint32_t nowMs, Drift& drift);

/// `heartbeat_seconds`, exact kind, clamped to the cadence bounds.
bool readHeartbeatSeconds(const jv::Value& body, uint32_t& intervalMs, Drift& drift);

/// Builds the shared structures from the images.
template <class RosterT> void applyRosterImage(const RosterImage& image, RosterT& target) {
  target.beginReplace(image.anchorMs);
  for (uint8_t i = 0U; i < image.count; ++i) {
    static_cast<void>(target.add(image.entries[i]));
  }
  target.commitReplace();
}

template <class KeyRingT> void applyCodeImage(const CodeImage& image, KeyRingT& ring) {
  ring.beginReplace();
  for (uint8_t s = 0U; s < memcode::kMaxDaySlots; ++s) {
    if (image.days[s].valid) {
      static_cast<void>(ring.setDay(s, image.days[s]));
    }
  }
  for (uint8_t i = 0U; i < image.count; ++i) {
    static_cast<void>(ring.add(image.keys[i]));
  }
  ring.commitReplace();
}

// --- one whole heartbeat answer ----------------------------------------------

/// Everything a heartbeat answer can change, apart from the lifeline (which
/// GateApp hands to the key ring, the network and the OTA runner).
struct GateBoardState {
  GateSettings settings = compiledGateSettings();
  RosterImage roster;
  CodeImage codes;
  StepImage step;
  uint32_t heartbeatMs = kGateConfig.heartbeatMs;
};

/// What one answer did.
struct HeartbeatRead {
  /// A 2xx carrying one complete object. Nothing else adopts anything.
  bool accepted = false;
  /// A 401: the caller retries once with the previous key (§6).
  bool authRetry = false;
  /// `kind` was not "gate": no roster, keys or settings were adopted (DG-9).
  bool kindMismatch = false;
  /// `unlock_seconds` arrived outside [1, 30] and was clamped.
  bool unlockClamped = false;
  ArrayRead roster = ArrayRead::Absent;
  ArrayRead days = ArrayRead::Absent;
  ArrayRead keys = ArrayRead::Absent;
  bool stepSynced = false;
  Drift drift;
  /// The lifeline objects' spans, present when the answer carried them —
  /// read from any accepted answer, whatever else in it drifted (§11.1).
  jv::Value ota;
  jv::Value keyNext;
  jv::Value net;
};

/// Reads one heartbeat answer into `state` by every rule above.
HeartbeatRead readHeartbeat(uint16_t status, const char* body, size_t len, uint32_t nowMs, GateBoardState& state);

// --- the scan decision and the events reply ---------------------------------

/// The `/gate` answer as §11.2 rule 6 reads it: 403 is out of service; a
/// readable 2xx (`opened` a bool, and `unlock_seconds` an integer when opened)
/// is decided by the body; anything else — every other status, a cut or HTML
/// 2xx, a reply as long as the buffer — is undecided and decided offline.
ScanDecision readScanReply(uint16_t status, const char* body, size_t len, uint32_t hardCapMs);

/// `accepted_through` from a 2xx events reply, exact kind. False otherwise.
bool readEventsReply(uint16_t status, const char* body, size_t len, uint32_t& acceptedThrough);

constexpr bool isSuccess(uint16_t status) {
  return status >= 200U && status <= 299U;
}

